<template><view class="page" v-if="book"><view class="detail glass"><image class="cover" :src="book.cover_url"/><view class="info"><text class="h1">{{book.title}}</text><text class="meta">{{(book.authors||[]).join('、')}} · {{book.publisher}} · ⭐ {{book.avg_rating}}</text><view class="tags"><text v-for="t in book.tags" :key="t" class="tag">{{t}}</text></view><text class="desc">{{book.description}}</text></view></view><view class="actions"><button class="btn" @click="reader">在线试读</button><button @click="shelf('想读')">加入书架</button><button @click="rate">评分</button></view><text class="title">相似推荐</text><BookCard v-for="b in similar" :key="b.id" :book="b" @tap="goDetail"/></view></template>
<script setup>import { ref,onMounted } from 'vue'; import { request } from '../../api/request'; import BookCard from '../../components/BookCard.vue'; const book=ref(null); const similar=ref([]); const id=ref(null); onMounted(async()=>{const pages=getCurrentPages(); id.value=pages[pages.length-1].options.id; book.value=await request('/books/'+id.value); const r=await request('/recommend/similar/'+id.value); similar.value=r.items||[]}); function reader(){uni.navigateTo({url:'/pages/reader/reader?id='+id.value})} async function shelf(name){await request('/ecosystem/shelves/book/'+id.value,{method:'POST',data:{shelf_name:name}}); uni.showToast({title:'已加入书架'})} async function rate(){await request('/user/rating/'+id.value,{method:'POST',data:{rating:5}}); uni.showToast({title:'评分已保存'})} function goDetail(b){uni.navigateTo({url:'/pages/detail/detail?id='+b.id})}</script><style scoped>.detail{display:flex;gap:24rpx;padding:26rpx}.cover{width:220rpx;height:320rpx;border-radius:28rpx}.h1{display:block;font-size:42rpx;font-weight:900}.meta,.desc{display:block;color:#667085;margin:10rpx 0;line-height:1.6}.tags{display:flex;gap:8rpx;flex-wrap:wrap}.tag{background:#f2f4f7;border-radius:999rpx;padding:6rpx 12rpx;font-size:22rpx}.actions{display:flex;gap:12rpx;margin:20rpx}.title{font-size:34rpx;font-weight:900;margin:20rpx;display:block}</style>
